&lt;table class=&quot;Bestiaire&quot;&gt;&lt;tr&gt;&lt;td&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Dragon lunaire adulte &lt;div style=&quot;float:right;&quot;&gt;FP 13&lt;/div&gt;&lt;/div&gt;
&lt;div style=&quot;float:right&quot;&gt;
&lt;img title=&quot;Dragon&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Dragon.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Ciel&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Ciel.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Extraplanaire&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Extraplanaire.png&quot; style=&quot;opacity: 1&quot; /&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;i&gt;Source : Bestiaire 4 page 75&lt;/i&gt;
&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;25 600 PX&lt;/li&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Type-Dragon.html&quot; title=&quot;Dragon&quot;&gt;Dragon&lt;/a&gt; de taille TG, CN&lt;/li&gt;&lt;li&gt;&lt;b&gt;Init &lt;/b&gt;+3 ; &lt;b&gt;Sens &lt;/b&gt;sens draconiques, vision dans les t&#233;n&#232;bres ; Perception +25&lt;/li&gt;&lt;li&gt;&lt;b&gt;Aura &lt;/b&gt;pr&#233;sence &#233;trang&#232;re (54 m, DD 23)&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;D&#233;fense&lt;/div&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;CA &lt;/b&gt;28, contact 7, pris au d&#233;pourvu 28 (Dex –1, naturelle +21, taille -2)&lt;/li&gt;&lt;li&gt;&lt;b&gt;pv &lt;/b&gt;200 (16d12+96)&lt;/li&gt;&lt;li&gt;&lt;b&gt;R&#233;f&lt;/b&gt; +9, &lt;b&gt;Vig &lt;/b&gt;+15, &lt;b&gt;Vol &lt;/b&gt;+16&lt;/li&gt;&lt;li&gt;&lt;b&gt;Capacit&#233; d&#233;fensive&lt;/b&gt; r&#233;flexion de la lumi&#232;re; RD 5/magie ; &lt;b&gt;Immunit&#233;s &lt;/b&gt;froid, paralysie, sommeil ; RM 24&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Attaque&lt;/div&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;VD &lt;/b&gt;12 m, creusement 6 m, vol 60 m (m&#233;diocre)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Corps &#224; corps&lt;/b&gt; morsure, +22 (2d8+12)&lt;ul&gt;&lt;li&gt;et 2 griffes, +22 (2d6+8)&lt;/li&gt;&lt;li&gt;et 2 ailes, +20 (2d6+4)&lt;/li&gt;&lt;li&gt;et coup de queue, +20 (2d8+12)&lt;/li&gt;&lt;/ul&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;Espace &lt;/b&gt;4,50 m ; &lt;b&gt;Allonge &lt;/b&gt;3 m (4,50 m avec la morsure)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Attaques sp&#233;ciales&lt;/b&gt; argent lunaire, &#233;crasement, souffle (ligne de 30 m, 12d8 froid, DD 23), souffle d&#233;concertant&lt;/li&gt;&lt;li&gt;&lt;b&gt;Pouvoirs magiques &lt;/b&gt;(&lt;b&gt;NLS &lt;/b&gt;16 ; concentration +21)&lt;ul&gt;&lt;li&gt;&lt;i&gt;&#192; volont&#233; &lt;/i&gt;— &lt;a class=&quot;pagelink&quot; href=&quot;Bulle-De-Vie.html&quot; title=&quot;Bulle de vie&quot;&gt;bulle de vie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Lumi&#232;res-Dansantes.html&quot; title=&quot;Lumi&#232;res dansantes&quot;&gt;lumi&#232;res dansantes&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Pleine-Lune.html&quot; title=&quot;Pleine lune&quot;&gt;pleine lune&lt;/a&gt;&lt;/li&gt;&lt;/ul&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;Sorts d’ensorceleur connus&lt;/b&gt; (&lt;b&gt;NLS &lt;/b&gt;7 ; concentration +12)&lt;ul&gt;&lt;li&gt;&lt;i&gt;3&#232;me (3/jour)&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;H&#233;ro&#239;sme.html&quot; title=&quot;H&#233;ro&#239;sme&quot;&gt;h&#233;ro&#239;sme&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Rapidit&#233;.html&quot; title=&quot;Rapidit&#233;&quot;&gt;rapidit&#233;&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;i&gt;2&#232;me (5/jour)&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;Flou.html&quot; title=&quot;Flou&quot;&gt;flou&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Image-Miroir.html&quot; title=&quot;Image miroir&quot;&gt;image miroir&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Lueurs-Hypnotiques.html&quot; title=&quot;Lueurs hypnotiques&quot;&gt;lueurs hypnotiques&lt;/a&gt; (DD 17)&lt;/li&gt;&lt;li&gt;&lt;i&gt;1er (7/jour)&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;Armure-De-Mage.html&quot; title=&quot;Armure de mage&quot;&gt;armure de mage&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Compr&#233;hension-Des-Langages.html&quot; title=&quot;Compr&#233;hension des langages&quot;&gt;compr&#233;hension des langages&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Disparition.html&quot; title=&quot;Disparition&quot;&gt;disparition&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;charge-&#201;lectrique.html&quot; title=&quot;D&#233;charge &#233;lectrique&quot;&gt;d&#233;charge &#233;lectrique&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Protection-Contre-Le-Mal.html&quot; title=&quot;Protection contre le Mal&quot;&gt;protection contre le Mal&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;i&gt;0 (&#224; volont&#233;) &lt;/i&gt;— &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-La-Magie.html&quot; title=&quot;D&#233;tection de la magie&quot;&gt;d&#233;tection de la magie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Lecture-De-La-Magie.html&quot; title=&quot;Lecture de la magie&quot;&gt;lecture de la magie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Lumi&#232;re.html&quot; title=&quot;Lumi&#232;re&quot;&gt;lumi&#232;re&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Manipulation-&#192;-Distance.html&quot; title=&quot;Manipulation &#224; distance&quot;&gt;manipulation &#224; distance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Prestidigitation.html&quot; title=&quot;Prestidigitation&quot;&gt;prestidigitation&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-(Capacit&#233;).html&quot; title=&quot;r&#233;sistance&quot;&gt;r&#233;sistance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Signature-Magique.html&quot; title=&quot;Signature magique&quot;&gt;signature magique&lt;/a&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Statistiques&lt;/div&gt;&lt;/li&gt;&lt;/ul&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;For &lt;/b&gt;27, &lt;b&gt;Dex &lt;/b&gt;9, &lt;b&gt;Con &lt;/b&gt;20, &lt;b&gt;Int &lt;/b&gt;20, &lt;b&gt;Sag&lt;/b&gt; 22, &lt;b&gt;Cha &lt;/b&gt;21&lt;/li&gt;&lt;li&gt;&lt;b&gt;BBA &lt;/b&gt;+16 ; &lt;b&gt;BMO &lt;/b&gt;+26 ; &lt;b&gt;DMD &lt;/b&gt;35 (39 contre croc-en-jambe)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dons &lt;/b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Assaut-H&#233;b&#233;tant.html&quot; title=&quot;Assaut h&#233;b&#233;tant&quot;&gt;Assaut h&#233;b&#233;tant&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Attaque-En-Puissance.html&quot; title=&quot;Attaque en puissance&quot;&gt;Attaque en puissance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Attaque-En-Vol.html&quot; title=&quot;Attaque en vol&quot;&gt;Attaque en vol&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Attaques-Multiples.html&quot; title=&quot;Attaques multiples&quot;&gt;Attaques multiples&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Frappe-Magique.html&quot; title=&quot;Frappe magique&quot;&gt;Frappe magique&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Robustesse.html&quot; title=&quot;Robustesse&quot;&gt;Robustesse&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-De-Linitiative.html&quot; title=&quot;Science de l&amp;#39;initiative&quot;&gt;Science de l’initiative&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Virage-Sur-Laile.html&quot; title=&quot;Virage sur l&amp;#39;aile&quot;&gt;Virage sur l’aile&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;Comp&#233;tences &lt;/b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt; +24, &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt; +12, &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (folklore local, g&#233;ographie, histoire, myst&#232;res, nature) +20, &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; +24, &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; +24, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +25, &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt; +25, &lt;a class=&quot;pagelink&quot; href=&quot;Utilisation-Dobjets-Magiques.html&quot; title=&quot;Utilisation d&amp;#39;objets magiques&quot;&gt;Utilisation d’objets magiques&lt;/a&gt; +24, &lt;a class=&quot;pagelink&quot; href=&quot;Vol.html&quot; title=&quot;Vol&quot;&gt;Vol&lt;/a&gt; +10,&lt;/li&gt;&lt;li&gt;&lt;b&gt;Langues &lt;/b&gt;a&#233;rien, aklo, aquatique, commun, draconique, ign&#233;&lt;/li&gt;&lt;li&gt;&lt;b&gt;Particularit&#233;s &lt;/b&gt;ne respire pas, vol stellaire&lt;br /&gt;&lt;/div&gt;&lt;br /&gt;&lt;/td&gt;&lt;td&gt;&lt;div&gt;&lt;ul style=&quot;margin: 0 0 -10 0;margin-top: 6px;margin-bottom: 12px;&quot;&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;Voir la description des &lt;a class=&quot;pagelink&quot; href=&quot;Dragon-Sid&#233;ral.html&quot; title=&quot;Les dragons sid&#233;raux&quot;&gt;dragons sid&#233;raux&lt;/a&gt;.&lt;/i&gt;&lt;/b&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;Voir la description des &lt;a class=&quot;pagelink&quot; href=&quot;Dragon-Sid&#233;ral.html&quot; title=&quot;Les dragons sid&#233;raux&quot;&gt;dragons sid&#233;raux&lt;/a&gt;.&lt;/i&gt;&lt;/b&gt;&lt;/li&gt;&lt;/ul&gt;&lt;i&gt;Un halo scintillant entoure la t&#234;te couronn&#233;e d’une cr&#234;te de ce majestueux dragon. Des reflets ondoient sur ses grandes ailes comme du tulle laiteux sous les rayons de la lune.&lt;/i&gt;  &lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;Les dragons lunaires interagissent souvent avec les mortels et passent de longues heures &#224; observer ce qui se passe sur les plan&#232;tes qui les int&#233;ressent.
&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
